import numpy as np

def shannon_fano_encoding(symbols, probabilities):
    sorted_items = sorted(zip(symbols, probabilities), key=lambda x: -x[1])

    def split(items):
        if len(items) == 1:
            return {items[0][0]: ''}

        total = sum(p for _, p in items)
        best_split = 1
        best_diff = float('inf')
        for i in range(1, len(items)):
            left_sum = sum(p for _, p in items[:i])
            diff = abs(2 * left_sum - total)
            if diff < best_diff:
                best_diff = diff
                best_split = i

        codes = {}
        left_codes = split(items[:best_split])
        right_codes = split(items[best_split:])
        for sym, code in left_codes.items():
            codes[sym] = '0' + code
        for sym, code in right_codes.items():
            codes[sym] = '1' + code
        return codes

    return split(sorted_items)

def kraft_inequality(code_lengths):
    kraft_sum = sum(2**(-l) for l in code_lengths)
    return kraft_sum <= 1.0 + 1e-10, kraft_sum

def source_coding_bound(probabilities):
    p = np.array(probabilities)
    p = p[p > 0]
    entropy = -np.sum(p * np.log2(p))
    optimal_lengths = np.ceil(-np.log2(p)).astype(int)
    avg_length = np.sum(np.array(probabilities) * optimal_lengths)
    return {'entropy': entropy, 'lower_bound': entropy, 'upper_bound': entropy + 1, 'avg_length': avg_length}

symbols = ['A', 'B', 'C', 'D', 'E']
probs = [0.35, 0.25, 0.20, 0.15, 0.05]
codes = shannon_fano_encoding(symbols, probs)
print(f"Shannon-Fano codes: {codes}")

lengths = [len(c) for c in codes.values()]
is_valid, k_sum = kraft_inequality(lengths)
print(f"Kraft inequality satisfied: {is_valid} (sum = {k_sum:.4f})")
